        let followingTabBar = app.tabBars.buttons["Following"]
        _ = followingTabBar.waitForExistence(timeout: 5)

        // Get all buttons in the app
        let buttons = app.buttons.allElementsBoundByIndex
        print("Total buttons found: \(buttons.count)")

        // Log buttons to find the more options button
        for (index, button) in buttons.enumerated() {
            if button.label.contains("...") || button.label.contains("More") || button.label.contains("menu") {
                print("Found potential more menu button at index \(index): '\(button.label)' at \(button.frame)")
            }
        }

        // The more options button (three dots) should be the rightmost button in the action row
        // From the screenshot we saw earlier, it's at approximately (669, 1103)
        // We need to convert that to normalized coordinates
        // The screen size appears to be 390x844 (iPhone size)
